def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    runs = _edge_runs(grid, 0, background) + _edge_runs(grid, w - 1, background)
    # The two long edge runs are the paired row bands; use the longest run
    # from each edge that has an equal-height counterpart on the other edge.
    left = [x for x in runs if x[2] == 0]
    right = [x for x in runs if x[2] == w - 1]
    pairs = [(a, b) for a in left for b in right if a[1] - a[0] == b[1] - b[0]]
    if pairs:
        a, b = max(pairs, key=lambda p: p[0][1] - p[0][0])
    elif left and right:
        a, b = max(((a, b) for a in left for b in right),
                   key=lambda p: min(p[0][1] - p[0][0], p[1][1] - p[1][0]))
    else:
        return out
    blocks = [a, b]
    border_color = a[3]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != border_color]
