        idx = r - src[0]
        if idx >= dst[1] - dst[0]:
            continue
        tr = dst[0] + idx
        # Extend the marker toward the source boundary, with a distinct cap.
        if src[2] == 0:
            for cc in range(src[2] + 1, c):
                out[r][cc] = color
        else:
            for cc in range(c + 1, src[2]):
